-- ============================================================
-- 003 — Drill seed, part 04 of 07  (40 drills)
--
-- Paste into the Supabase SQL editor and run. Parts are independent and
-- idempotent: re-running one updates those rows rather than duplicating them.
--
-- Requires scripts/002_drill_content.sql to have been applied first.
-- ============================================================

INSERT INTO public.drills (
  slug, name, category, subcategory, type, level, duration_min, player_count, group_size, description, objective, setup, instructions, coaching_cues, common_errors, variations, tags, diagram_type, diagram_data
) VALUES
  ('SV-006', 'Serve and Volley: T Serve into Net Rush', 'Serve', 'Flat', 'serve', 'advanced', 12, 2, 'pairs', 'Develop the serve-and-volley pattern — one of the most aggressive and aesthetically complete tactics in tennis. Player 1 serves to the T to limit the return angles, then rushes the net and finishes with a volley. The serve-and-volley puts immediate pressure on the returner and is devastatingly effective on fast courts, against players who need time, and as a surprise tactic against baseliners.', 'Develop the serve-and-volley pattern — one of the most aggressive and aesthetically complete tactics in tennis. Player 1 serves to the T to limit the return angles, then rushes the net and finishes with a volley. The serve-and-volley puts immediate pressure on the returner and is devastatingly effective on fast courts, against players who need time, and as a surprise tactic against baseliners.', 'Player 1 serves from the deuce court to the T, then immediately sprints to the net. Player 2 attempts a passing shot. Player 1 must split step before the pass and volley the finish.', ARRAY['Player 1 serves flat to the T from the deuce court.','The moment the serve leaves the racket, Player 1 sprints toward the net.','Player 1 performs a split step as Player 2''s racket contacts the ball.','Player 2 attempts a passing shot — Player 1 volleys the finish.','Play out each point. Repeat 15 times. Track percentage of points won after serve-and-volley.']::text[], ARRAY['Move immediately after the serve — don''t watch the serve land before starting the sprint.','Target the T — it limits the returner''s angles and makes the passing shot harder.','Split step as Player 2 hits — not after the ball is already in flight.','Don''t rush the volley — take one more step toward the ball before swinging.','Get inside the service line before split stepping if possible — closer net position is always better.']::text[], ARRAY['Hesitating after the serve — if not already moving, the volley position is unreachable.','No split step — reactive volleys without a split step are always late.','Volleying from too far back — standing at the service line instead of closer to the net.']::text[], ARRAY['Wide serve plus serve-and-volley: wide slice to open the court, then rush the net.','Second serve and volley: much harder — must use spin serve and still rush the net.','Doubles serve-and-volley: partner already at net, server rushes after the serve — classic pattern.']::text[], ARRAY['serve','volley','net rush','advanced','flat','tactical']::text[], 'json', '{"p1":{"x":200,"y":560},"p2":{"x":120,"y":60},"moves":[{"x1":240,"y1":855,"x2":200,"y2":560}],"shots":[{"x1":240,"y1":855,"x2":200,"y2":370},{"x1":120,"y1":70,"x2":195,"y2":620},{"x1":195,"y1":555,"x2":310,"y2":120}],"areas":[{"x":310,"y":120,"r":25}]}'::jsonb),
  ('SV-007', 'Serve Placement: Three-Zone Rotation', 'Serve', 'Flat', 'serve', 'intermediate', 12, 2, 'pairs', 'Develop the ability to deliberately place the serve to all three zones — wide, T, and body — from both the deuce and ad courts. Serving to only one or two locations is the most common tactical mistake recreational and club players make. This drill trains the habit of mixing serve locations intentionally, making the serve unpredictable and forcing the returner to stay guessing.', 'Develop the ability to deliberately place the serve to all three zones — wide, T, and body — from both the deuce and ad courts. Serving to only one or two locations is the most common tactical mistake recreational and club players make. This drill trains the habit of mixing serve locations intentionally, making the serve unpredictable and forcing the returner to stay guessing.', 'Player 1 serves from both courts. Three cones mark the three target zones in each service box: wide corner, T (center line), and body (middle of the box). Player 2 reads and returns.', ARRAY['Player 1 serves from the deuce court, rotating in order: T, wide, body, T, wide, body.','After 6 deuce court serves, switch to the ad court: T, wide, body rotation.','Player 2 calls the location (''T'', ''wide'', ''body'') after each serve lands.','If Player 1 hits the wrong zone, it does not count — must hit the intended zone.','Track accuracy: how many of each zone does Player 1 hit correctly out of 10?']::text[], ARRAY['The toss determines the location — practice each toss position separately if needed.','T serve: toss slightly inside (left for right-handers).','Wide serve: toss slightly outside (right for right-handers).','Body serve: toss in the middle — same as T serve but aim at the returner''s body.','Each placement should use the same pre-serve routine — disguise comes from routine consistency.']::text[], ARRAY['Same toss for every serve — Player 2 reads the placement from the toss alone.','Only serving to comfortable zones — must serve to all three equally.','Not tracking which zone is landing consistently — need data to improve placement accuracy.']::text[], ARRAY['Player 2 guesses the zone before the serve — Player 1 must mix well to prevent guessing.','Score: +1 for landing in the intended zone, +2 if it is unreturnable.','Speed versus placement: try serves at 70% pace for placement, then 90% pace — does accuracy hold?']::text[], ARRAY['serve','placement','three zones','tactical','intermediate','both courts']::text[], 'json', '{"p1":{"x":240,"y":860},"p2":{"x":120,"y":60},"shots":[{"x1":240,"y1":850,"x2":200,"y2":370},{"x1":240,"y1":850,"x2":320,"y2":390},{"x1":240,"y1":850,"x2":150,"y2":375}],"cones":[{"x":200,"y":370},{"x":320,"y":390},{"x":150,"y":375}]}'::jsonb),
  ('SV-008', 'Wide Kick Serve: Ad Court Backhand Weapon', 'Serve', 'Kick', 'serve', 'advanced', 12, 2, 'pairs', 'Develop the wide kick serve from the ad court — a serve that curves outward and kicks high to the returner''s backhand, pulling them off the court while forcing a high and uncomfortable return. This is one of the most complete serves in the game: it pulls the returner wide, kicks high above their backhand, and opens the entire court for the next shot. Professional players use this serve to set up easy third-ball forehands.', 'Develop the wide kick serve from the ad court — a serve that curves outward and kicks high to the returner''s backhand, pulling them off the court while forcing a high and uncomfortable return. This is one of the most complete serves in the game: it pulls the returner wide, kicks high above their backhand, and opens the entire court for the next shot. Professional players use this serve to set up easy third-ball forehands.', 'Player 1 serves from the ad court targeting the wide corner of the deuce service box. Player 2 returns from the deuce side. The serve should curve wide and kick high — pulling Player 2 off the court.', ARRAY['Player 1 serves a wide kick serve from the ad court, targeting the wide corner of the deuce service box.','The serve should curve outward and kick upward after the bounce.','Player 2 attempts to return from a wide, off-balance position.','After each serve, Player 1 plays out the point — exploiting the open court.','Track: how many wide kick serves pull Player 2 at least 2 feet outside the singles sideline? Target: 6 out of 10.']::text[], ARRAY['Toss behind and to the right (for right-handers) — slightly further right than a deuce court kick.','Swing from 7 o''clock across to 1 o''clock — same motion as the standard kick but aimed further outside.','The ball must kick outward as well as upward — sidespin plus topspin creates both movements.','The wider the kick goes, the more open the court becomes — perfect third-ball setup.','Follow through hard and across — the cross-body finish drives the sidespin.']::text[], ARRAY['Serve goes too close to the center — not wide enough, returner can hit comfortably.','All topspin and no sidespin — ball kicks high but not wide enough.','Toss too far forward — cannot generate the kick motion from a forward toss.']::text[], ARRAY['Wide kick then inside-in: kick pulls Player 2 wide, Player 1 hits inside-in forehand to the open court.','Wide kick second serve: use this serve as the second serve — high margin, high kick.','Doubles: wide kick from the ad court creates a sharper angle away from the net player.']::text[], ARRAY['serve','kick','wide','ad court','advanced','backhand weapon']::text[], 'json', '{"p1":{"x":160,"y":860},"p2":{"x":280,"y":60},"shots":[{"x1":160,"y1":850,"x2":320,"y2":385}],"areas":[{"x":320,"y":385,"r":22}],"cones":[{"x":320,"y":385}]}'::jsonb),
  ('SV-009', 'Serve Toss Consistency Drill', 'Serve', 'Flat', 'serve', 'beginner', 10, 1, 'individual', 'Isolate and train the ball toss — the most underrated and most impactful component of a consistent serve. An inconsistent toss means an inconsistent serve every single time. If the toss location varies, the entire swing must compensate, which introduces errors. This drill develops a repeatable, consistent toss that lands in exactly the same position on every serve.', 'Isolate and train the ball toss — the most underrated and most impactful component of a consistent serve. An inconsistent toss means an inconsistent serve every single time. If the toss location varies, the entire swing must compensate, which introduces errors. This drill develops a repeatable, consistent toss that lands in exactly the same position on every serve.', 'Player 1 stands at the baseline with a basket of balls. No racket is needed for the first phase. Player 1 simply tosses the ball and lets it drop, marking where it lands on the court relative to their foot position.', ARRAY['Phase 1: Player 1 tosses the ball without hitting and lets it land on the court. Observe where it lands — is it consistent?','Mark the ideal toss spot with a cone: slightly in front of the left foot and 6 inches to the right (for right-handers).','Toss 20 balls aiming for the cone. Count how many land within 6 inches of the cone.','Phase 2: add the swing — toss and serve, checking if the toss position is still consistent.','Target: 15 out of 20 tosses landing in the ideal zone.']::text[], ARRAY['Release the ball from your fingertips — don''t spin or toss it like a basketball.','Raise the arm smoothly without bending the elbow — a straight, smooth lift is the key.','Release at the top of the arm''s reach — not before, not after.','Look up at the toss immediately — track the ball with your eyes from the moment it leaves your hand.','Practice the toss without swinging until it is extremely consistent — then add the swing.']::text[], ARRAY['Spinning the ball on release — creates an inconsistent, rotating toss every time.','Bending the elbow during the toss — introduces a launching motion that changes the height.','Releasing the ball too early — toss goes too high, forcing a timing adjustment.']::text[], ARRAY['Toss to different positions deliberately: inside for T serve, outside for wide — teaches position variation.','Film the toss from the side: check if the arm is straight and the release point is consistent.','Partner call: Player 2 calls ''yes'' or ''no'' based on whether the toss looked consistent — external feedback.']::text[], ARRAY['serve','toss','technique','beginner','solo','foundation']::text[], 'json', '{"p1":{"x":200,"y":860},"shots":[{"x1":200,"y1":850,"x2":200,"y2":390}],"areas":[{"x":200,"y":390,"r":30}],"cones":[{"x":200,"y":390}]}'::jsonb),
  ('SV-010', 'Serve Plus One: Wide Serve into Forehand Attack', 'Serve', 'Flat', 'serve', 'intermediate', 12, 2, 'pairs', 'Develop the wide serve plus one forehand pattern — one of the most reliable point-construction patterns in tennis. The wide serve pulls the returner off the court, creating a large open space on the deuce side. Player 1 then hits an aggressive forehand into that open space to finish the point. This two-shot pattern is the foundation of serve-dominant offensive tennis and works at all levels.', 'Develop the wide serve plus one forehand pattern — one of the most reliable point-construction patterns in tennis. The wide serve pulls the returner off the court, creating a large open space on the deuce side. Player 1 then hits an aggressive forehand into that open space to finish the point. This two-shot pattern is the foundation of serve-dominant offensive tennis and works at all levels.', 'Player 1 serves wide from the deuce court. Player 2 returns from outside the singles sideline. Player 1 anticipates the likely cross-court return and hits an aggressive forehand into the open deuce side.', ARRAY['Player 1 serves wide from the deuce court, pulling Player 2 outside the singles sideline.','Player 2 returns — the return will likely come cross-court to Player 1''s forehand side.','Player 1 moves toward center or forehand and hits an aggressive forehand into the open deuce side.','Play out the point after the forehand — test what happens when the forehand is not a clean winner.','Repeat 15 times. Track: how many open-court forehands land in the target zone?']::text[], ARRAY['Move toward the forehand the moment the serve leaves the racket — don''t wait.','The wide serve creates a likely CC return — read it early and be in position.','Your forehand target is the open deuce side — the court Player 2 vacated.','Hit the forehand inside-in or straight — wherever the open court is.','If the return goes to your backhand instead, be ready to redirect or slice.']::text[], ARRAY['Not moving after the serve — caught flat-footed as the return arrives.','Wide serve not wide enough — doesn''t pull Player 2 off the court, leaves no open space.','Forehand going cross-court instead of to the open deuce side — hitting to the wrong target.']::text[], ARRAY['Wide serve plus drop shot: fake the forehand, hit a drop shot into the vacated court.','Wide serve to backhand: pull the player wide to their backhand, then attack the forehand side.','Three-ball pattern: wide serve, plus-one forehand, plus-two finishing shot — full point construction.']::text[], ARRAY['serve','serve+1','wide','forehand','pattern','intermediate','tactical']::text[], 'json', '{"p1":{"x":280,"y":840},"p2":{"x":340,"y":60},"moves":[{"x1":240,"y1":855,"x2":280,"y2":840}],"shots":[{"x1":240,"y1":855,"x2":325,"y2":390},{"x1":340,"y1":70,"x2":245,"y2":800},{"x1":280,"y1":840,"x2":310,"y2":100}],"areas":[{"x":310,"y":100,"r":30}]}'::jsonb),
  ('GW-001', 'Cross-Court Forehand Consistency Rally', 'Groundwork', 'Forehand', 'groundstrokes', 'beginner', 10, 2, 'pairs', 'Build muscle memory and consistency for the cross-court forehand. The cross-court is the highest-percentage shot in tennis — it travels over the lowest part of the net, covers the longest distance of the court, and gives the most margin for error. This drill trains players to own that shot under low-pressure repetition until it becomes completely automatic.', 'Build muscle memory and consistency for the cross-court forehand. The cross-court is the highest-percentage shot in tennis — it travels over the lowest part of the net, covers the longest distance of the court, and gives the most margin for error. This drill trains players to own that shot under low-pressure repetition until it becomes completely automatic.', 'Both players start at their respective baselines. Player 1 (Student, orange) stands on the deuce side. Player 2 (Coach, blue) stands on the ad side of the opposite baseline. Both players rally cross-court forehands only — no down-the-line shots allowed during this drill.', ARRAY['Player 2 initiates with a medium-pace feed to Player 1''s forehand wing on the deuce side.','Player 1 returns cross-court to Player 2''s forehand wing, aiming for the shaded target area deep in the corner.','Both players continue rallying cross-court only, maintaining a steady rhythm.','If the ball lands outside the target zone or goes DTL, play resets with a new feed from Player 2.','Switch sides after 5 minutes so Player 1 practices from the ad side as well.']::text[], ARRAY['Unit turn early — rotate your shoulders as soon as the ball leaves the opponent''s racket.','Contact point in front of your lead hip, not beside your body.','Finish high over the opposite shoulder — your racket should end near your left ear for right-handers.','Stay on your toes between shots — weight always forward, never flat-footed.','Aim 3 feet over the net, not just barely over it — give yourself a real margin.']::text[], ARRAY['Late preparation causing a blocked or pushed shot with no pace.','Hitting down on the ball instead of brushing up for topspin.','Standing flat-footed between shots, leading to late movement and rushed swings.']::text[], ARRAY['Add a cone at the target — award a point each time the cone is hit to build precision.','Play out the point freely after 4 successful cross-court shots have been landed.','Introduce a time limit: how many consecutive shots can both players land in the target zone in 60 seconds?']::text[], ARRAY['forehand','cross-court','consistency','baseline','topspin','beginner']::text[], 'json', '{"p1":{"x":280,"y":860},"p2":{"x":120,"y":60},"shots":[{"x1":280,"y1":850,"x2":100,"y2":90},{"x1":100,"y1":70,"x2":270,"y2":840}],"areas":[{"x":100,"y":110,"r":30},{"x":280,"y":820,"r":30}]}'::jsonb),
  ('GW-002', 'Inside-Out Forehand Attack', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 12, 2, 'pairs', 'Train the inside-out forehand — one of the most powerful offensive weapons in modern tennis. The player moves around their backhand to run a forehand cross-court to the opponent''s backhand corner. This shot creates extreme angles, puts the opponent on the defensive immediately, and allows the stronger forehand to dominate the rally from a position that normally demands a backhand.', 'Train the inside-out forehand — one of the most powerful offensive weapons in modern tennis. The player moves around their backhand to run a forehand cross-court to the opponent''s backhand corner. This shot creates extreme angles, puts the opponent on the defensive immediately, and allows the stronger forehand to dominate the rally from a position that normally demands a backhand.', 'Player 2 stands at the baseline on the deuce side and feeds a ball toward Player 1''s backhand (center-left area). Player 1 starts at the center mark and must move left to hit an inside-out forehand targeting the deep ad-side corner.', ARRAY['Player 2 feeds a medium-paced ball to Player 1''s backhand side, slightly left of center.','Player 1 reads the ball early and shuffles left, getting around the ball to hit a forehand instead of a backhand.','Player 1 hits the inside-out forehand cross-court, targeting the deep ad-side corner inside the target area.','Player 1 recovers back to the center of the baseline after the shot.','Repeat 15 times, then switch roles. Track how many balls land in the target zone.']::text[], ARRAY['Recognize the opportunity early — the ball must be short enough or slow enough to run around comfortably.','Move laterally first, then step forward into the ball — don''t reach across your body.','Keep the swing path from low-to-high and inside-out — don''t pull the ball accidentally down-the-line.','After contact, push off your outside foot and recover immediately to center.','The more open your stance, the easier and faster the recovery back to center.']::text[], ARRAY['Hitting DTL accidentally by pulling across the body too early in the swing.','Failing to recover to center after the shot, leaving the entire DTL side wide open.','Not getting far enough around the ball and ending up hitting a weak, cramped backhand instead.']::text[], ARRAY['Player 2 can choose any corner after Player 1 hits the inside-out — play the point out fully.','Constraint drill: Player 1 must hit 3 inside-out forehands in a row before being allowed to change direction.','Add a cone at the far corner target for precision tracking — count how many times the cone zone is hit.']::text[], ARRAY['forehand','inside-out','offensive','footwork','intermediate','pattern']::text[], 'json', '{"p1":{"x":110,"y":850},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":850,"x2":110,"y2":850}],"shots":[{"x1":200,"y1":70,"x2":160,"y2":840},{"x1":110,"y1":840,"x2":95,"y2":100}],"areas":[{"x":95,"y":100,"r":30}]}'::jsonb),
  ('GW-003', 'Backhand Cross-Court Consistency Rally', 'Groundwork', 'Backhand', 'groundstrokes', 'beginner', 10, 2, 'pairs', 'Build a reliable, consistent cross-court backhand. The backhand cross-court is the natural high-percentage response to a forehand attack from the deuce side and is essential for all neutral baseline play. Many players neglect this shot in practice, which is why it breaks down under match pressure — this drill fixes that by dedicating focused time to it.', 'Build a reliable, consistent cross-court backhand. The backhand cross-court is the natural high-percentage response to a forehand attack from the deuce side and is essential for all neutral baseline play. Many players neglect this shot in practice, which is why it breaks down under match pressure — this drill fixes that by dedicating focused time to it.', 'Player 1 stands on the ad side of the baseline (left side for right-handers). Player 2 stands on the deuce side of the opposite baseline. Both rally cross-court backhands only — no down-the-line shots during this drill.', ARRAY['Player 2 initiates with a relaxed, easy feed to Player 1''s backhand on the ad side.','Player 1 returns cross-court, targeting the deep deuce corner inside the target zone.','Maintain a steady rally rhythm — no power, just controlled placement and depth.','If a shot lands outside the target zone, reset without stopping — both players learn from the miss.','Switch player positions after 5 minutes so both players drill the same pattern.']::text[], ARRAY['For two-handers: keep both hands on the racket through the entire swing — not just the backswing.','Shoulder turn is essential — get your front shoulder pointing toward the back fence.','Contact slightly in front of the lead hip, not behind it — this is where power comes from.','Follow through toward the target, then let the racket wrap around your shoulder naturally.','Use your legs — bend your knees on the backswing, then drive up through contact.']::text[], ARRAY['Dropping the non-dominant hand too early on a two-hander — creates a weak, arm-only shot with poor direction.','Not rotating the shoulders back far enough — results in a weak push with no power.','Hitting up on the ball instead of through it — causes the ball to float without depth.']::text[], ARRAY['Add a depth cone 6 feet inside the baseline — only balls landing past it count toward the target.','After 6 consecutive exchanges, play out the point freely with any shot.','One player hits topspin, the other flat — discuss how the different spins affect the bounce and timing.']::text[], ARRAY['backhand','cross-court','consistency','baseline','beginner']::text[], 'json', '{"p1":{"x":120,"y":860},"p2":{"x":280,"y":60},"shots":[{"x1":120,"y1":850,"x2":290,"y2":90},{"x1":280,"y1":70,"x2":110,"y2":840}],"areas":[{"x":290,"y":110,"r":30},{"x":110,"y":820,"r":30}]}'::jsonb),
  ('GW-004', 'Backhand Down-the-Line Attack', 'Groundwork', 'Backhand', 'groundstrokes', 'intermediate', 12, 2, 'pairs', 'Develop the ability to redirect the ball down-the-line off the backhand wing. This is a crucial change-of-direction shot — it switches the play entirely, opens the court, and is most effective when disguised to look like a cross-court ball until the very last moment. The ability to go DTL from the backhand is what separates intermediate players from competitive ones.', 'Develop the ability to redirect the ball down-the-line off the backhand wing. This is a crucial change-of-direction shot — it switches the play entirely, opens the court, and is most effective when disguised to look like a cross-court ball until the very last moment. The ability to go DTL from the backhand is what separates intermediate players from competitive ones.', 'Player 2 feeds from the deuce side baseline toward Player 1''s backhand side consistently. Player 1 must redirect the ball down-the-line to the deuce-side corner on their opponent''s side, instead of hitting cross-court.', ARRAY['Player 2 feeds a steady ball to Player 1''s backhand corner at medium pace.','Player 1 sets up as if hitting cross-court, with shoulders closed and body angled cross-court.','At the last moment, Player 1 redirects down-the-line by delaying the hip rotation and driving through the ball.','Player 1 targets the deep deuce corner, aiming inside the singles sideline.','After 15 DTL attempts, switch to cross-court for 15 reps — the comparison builds awareness of the exact difference.']::text[], ARRAY['Disguise: your setup and backswing should look completely identical to your cross-court backhand.','To redirect DTL: delay hip rotation slightly and keep your shoulders more closed at contact.','Contact point is slightly further back than your cross-court swing — the ball stays on the strings a fraction longer.','Drive through the ball aggressively — DTL shots have less net clearance margin so add controlled pace.','Recover immediately to center after the DTL — your shot opens your own court on the CC side.']::text[], ARRAY['Opening up the hips too early — telegraphs the DTL direction to the opponent before contact.','Hitting too late and floating the ball — ends up mid-court or in the net from lack of drive.','Not recovering fast enough after the DTL — leaves the cross-court completely exposed.']::text[], ARRAY['Play out the point after the DTL — Player 2 can go anywhere they want to test Player 1''s court coverage.','Score tracking: +2 for DTL winner, +1 for DTL that stays in and is deep, 0 for error.','Introduce a shadow: Player 2 starts moving as if expecting cross-court — Player 1 must still redirect DTL.']::text[], ARRAY['backhand','down-the-line','redirection','disguise','intermediate']::text[], 'json', '{"p1":{"x":120,"y":820},"p2":{"x":280,"y":60},"moves":[{"x1":120,"y1":850,"x2":120,"y2":820}],"shots":[{"x1":280,"y1":70,"x2":110,"y2":780},{"x1":120,"y1":820,"x2":90,"y2":100}],"areas":[{"x":90,"y":100,"r":25}]}'::jsonb),
  ('GW-005', 'Forehand Topspin Depth Control', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Train the forehand to consistently land deep in the court — between the service line and baseline. Deep groundstrokes push the opponent behind the baseline, reduce the angles available to them, and force short balls that can be attacked. This drill teaches players to treat depth as a deliberate tactical weapon, not just a byproduct of swinging hard.', 'Train the forehand to consistently land deep in the court — between the service line and baseline. Deep groundstrokes push the opponent behind the baseline, reduce the angles available to them, and force short balls that can be attacked. This drill teaches players to treat depth as a deliberate tactical weapon, not just a byproduct of swinging hard.', 'Place a rope, cone line, or tape across the court 6 feet inside the baseline, creating a clearly marked target zone between the service line and the baseline. Player 2 feeds from the opposite baseline. Player 1 must land every forehand inside that final 6-foot deep zone.', ARRAY['Player 2 feeds medium-paced balls alternating to Player 1''s forehand side.','Player 1 must land every ball in the deep target zone — the last 6 feet before the baseline.','A ball landing between the service line and the target rope scores 1 point. A ball past the rope (deepest 6 feet) scores 2 points.','Balls landing short of the service line score 0. Balls going out score -1.','Play 20 balls per set. Target score: 25+ points per set.']::text[], ARRAY['Think net clearance first — aim 3-4 feet over the net to give the ball enough arc to land deep.','Full swing every time, not a poke — truncated swings consistently produce short balls.','Load your legs before every shot — power and depth come from the ground, not the arm.','Watch the ball land — train your eye to see depth and adjust in real-time.','Follow through all the way to the end — stopping early at the follow-through kills depth and spin.']::text[], ARRAY['Swinging too flat — ball skids fast but lacks enough arc to consistently land deep.','Short backswing resulting in a weak push shot that lands short.','Eyes off the ball at contact — leads to mis-hits and wildly inconsistent depth.']::text[], ARRAY['Increase pressure: only 2 errors allowed before resetting the score back to zero.','Player 1 must call ''deep'' or ''short'' before the ball bounces — builds real-time anticipatory depth awareness.','Player 2 varies pace and spin unpredictably — Player 1 must adjust depth control on every different ball.']::text[], ARRAY['forehand','depth','topspin','consistency','intermediate','tactical']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":70,"x2":200,"y2":800},{"x1":200,"y1":840,"x2":200,"y2":120}],"areas":[{"x":200,"y":110,"r":35},{"x":200,"y":820,"r":35}]}'::jsonb),
  ('GW-006', 'Slice Backhand Neutralizer', 'Groundwork', 'Slice', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Develop a reliable slice backhand that stays low, travels deep, and neutralizes the opponent''s pace. The slice is an essential defensive and tactical tool — it changes rhythm, disrupts an aggressive baseliner, keeps the ball low on fast surfaces, and is critical on low balls or wide balls that simply cannot be hit with topspin. Every competitive player needs this shot.', 'Develop a reliable slice backhand that stays low, travels deep, and neutralizes the opponent''s pace. The slice is an essential defensive and tactical tool — it changes rhythm, disrupts an aggressive baseliner, keeps the ball low on fast surfaces, and is critical on low balls or wide balls that simply cannot be hit with topspin. Every competitive player needs this shot.', 'Player 2 feeds from the baseline to Player 1''s backhand side consistently. Player 1 returns with a slice backhand every single time — no topspin allowed. The target is the deep cross-court corner — the ball should bounce low and skid through the court without rising.', ARRAY['Player 2 feeds balls to Player 1''s backhand at medium pace.','Player 1 responds with a slice backhand every time — no topspin allowed during this drill.','Target: land the slice deep in the last 6 feet of the cross-court corner.','After 10 consecutive slices, Player 2 feeds a short ball — Player 1 approaches the net off the slice.','Reset and repeat the sequence. Focus on keeping the slice low and skidding through the court.']::text[], ARRAY['High to low racket path — start the racket well above the ball and finish below the contact point.','Open racket face at contact — roughly 30-40 degrees open, as if presenting a tray.','Don''t chop down aggressively — think ''guide and slice'' rather than ''slap downward''.','Stay sideways through contact — opening up the body early creates a floated, weak slice.','Aim for the net tape level, not 3 feet over — the slice should barely clear the net and stay low.']::text[], ARRAY['Floating the slice too high — gives the opponent an easy attack ball to drive.','Chopping down too aggressively — puts the ball straight into the net.','Opening the body too early — kills the direction control and pace of the slice.']::text[], ARRAY['Slice vs. topspin rally: Player 2 hits topspin, Player 1 must slice every ball — teaches managing different spins.','Defensive slice under pace: Player 2 hits hard and fast, Player 1 must absorb it and slice deep.','Approach off the slice: add a volley as the final shot after the approach to the net.']::text[], ARRAY['slice','backhand','neutral','defensive','spin','intermediate']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":280,"y":60},"shots":[{"x1":280,"y1":70,"x2":110,"y2":800},{"x1":110,"y1":830,"x2":290,"y2":100}],"areas":[{"x":290,"y":110,"r":30}]}'::jsonb),
  ('GW-007', 'Forehand–Backhand Alternating Baseline Rally', 'Groundwork', 'Forehand', 'groundstrokes', 'beginner', 12, 2, 'pairs', 'Train both groundstrokes equally by alternating forehand and backhand in a structured, predictable pattern. This drill develops the transition footwork between wings, the split step timing, and the ability to switch between two completely different swing paths rapidly — a skill demanded on every single rally in a match.', 'Train both groundstrokes equally by alternating forehand and backhand in a structured, predictable pattern. This drill develops the transition footwork between wings, the split step timing, and the ability to switch between two completely different swing paths rapidly — a skill demanded on every single rally in a match.', 'Player 2 feeds alternating balls — first to Player 1''s forehand, then to the backhand, then forehand again, creating a clear, predictable alternating pattern. Player 1 must move laterally between shots and hit each ball with full preparation, not just reaching.', ARRAY['Player 1 starts at the center mark in the ready position.','Player 2 feeds to the forehand — Player 1 moves, hits with full swing, recovers back to center.','Player 2 immediately feeds to the backhand — Player 1 moves, hits with full swing, recovers back to center.','Continue alternating for 10 exchanges, then rest 30 seconds. Repeat 3 sets.','Increase the pace of the feeds after each set — the recovery window between shots gets shorter.']::text[], ARRAY['Split step as Player 2''s racket contacts the ball — this is the exact timing cue to load and explode.','First step is always lateral, not forward or backward — move sideways to the ball.','Recover to center every single time — don''t cheat by staying on one side anticipating.','Change your grip between forehand and backhand during the sprint — build the habit now.','Keep your eyes on the ball through the entire flight from Player 2''s racket to yours.']::text[], ARRAY['Not recovering to center between shots — leaves one side completely open on the next ball.','Forgetting to change grip during the transition — results in hitting the backhand with a forehand grip.','Late split step — causes late preparation, rushed footwork, and poor contact on every shot.']::text[], ARRAY['Increase the width of the feeds progressively to push Player 1 further off the court.','Add a third ball down the middle — Player 1 must decide forehand or backhand based on court position.','Play out the point freely after the 4th alternating exchange — reward good rally work with real play.']::text[], ARRAY['forehand','backhand','alternating','footwork','beginner','transition']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":850,"x2":290,"y2":850},{"x1":290,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":110,"y2":850}],"shots":[{"x1":200,"y1":70,"x2":290,"y2":840},{"x1":200,"y1":60,"x2":110,"y2":840}],"areas":[{"x":200,"y":100,"r":40}]}'::jsonb),
  ('GW-008', 'Open-Stance Forehand Under Pressure', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Train the open-stance forehand — the shot used when there is not enough time to set up in a closed or semi-open stance. Modern tennis demands that players generate full power and spin from a wide, open stance. This drill simulates the pace and width that force an open-stance response and teaches players to rotate explosively from a planted outside foot.', 'Train the open-stance forehand — the shot used when there is not enough time to set up in a closed or semi-open stance. Modern tennis demands that players generate full power and spin from a wide, open stance. This drill simulates the pace and width that force an open-stance response and teaches players to rotate explosively from a planted outside foot.', 'Player 2 feeds fast balls wide to Player 1''s forehand corner — well outside the singles sideline if possible. Player 1 must sprint wide, plant their outside foot, and hit from a fully open stance. Stepping into the ball is not allowed — the drill specifically trains the planted open-stance rotation.', ARRAY['Player 2 hits a hard, wide ball to Player 1''s forehand corner.','Player 1 sprints wide, plants the right foot (for right-handers), and hits from a fully open stance.','Player 1 must return cross-court — DTL is too risky from such a wide position.','Player 1 recovers quickly to the center mark immediately after the shot.','Repeat 12 times per set. Rest 60 seconds between sets. Play 3 sets.']::text[], ARRAY['Plant the outside foot firmly — your right foot is the pivot point for your entire rotation.','Drive explosively off the outside foot as you swing — it''s your only power source from this stance.','Rotate hips fully through the shot — the legs do the work, the arm just guides.','Add topspin intentionally — open-stance forehands tend to float flat without a conscious brushing motion.','Cross-court is the right target: the angle is geometrically easier from a wide open stance.']::text[], ARRAY['Arm-swinging without hip rotation — produces a weak, arm-only shot that floats out.','Planting too close to the ball — no room to swing, causes a cramped, powerless contact.','Not recovering after the wide shot — leaves the entire court exposed for the next ball.']::text[], ARRAY['Add a recovery sprint: after the open-stance forehand, Player 2 immediately hits a winner to the other side.','Vary the pace — some balls fast, some medium — Player 1 must adjust and still use open stance.','Open-stance approach: on a slower wide ball, Player 1 can approach the net after the open-stance forehand.']::text[], ARRAY['forehand','open-stance','wide ball','pressure','intermediate']::text[], 'json', '{"p1":{"x":340,"y":855},"p2":{"x":120,"y":60},"moves":[{"x1":200,"y1":850,"x2":340,"y2":855}],"shots":[{"x1":120,"y1":70,"x2":340,"y2":840},{"x1":340,"y1":848,"x2":90,"y2":100}],"areas":[{"x":90,"y":100,"r":30}]}'::jsonb),
  ('GW-009', 'Slice Approach Shot Down the Line', 'Groundwork', 'Slice', 'groundstrokes', 'intermediate', 12, 2, 'pairs', 'Master the slice backhand as an approach shot — a low, skidding ball that forces the opponent to hit upward, making an easy volley for the approaching player. The slice approach is one of the most effective tools in baseline-to-net transitions because it stays low, moves through the court quickly, and gives the approaching player ample time to reach a solid net position.', 'Master the slice backhand as an approach shot — a low, skidding ball that forces the opponent to hit upward, making an easy volley for the approaching player. The slice approach is one of the most effective tools in baseline-to-net transitions because it stays low, moves through the court quickly, and gives the approaching player ample time to reach a solid net position.', 'Player 2 feeds a short ball (around the service line) to Player 1''s backhand side. Player 1 must move in decisively, hit a slice approach shot down-the-line, and follow the shot to the net position.', ARRAY['Player 2 feeds a short ball to Player 1''s backhand landing around the service line area.','Player 1 moves forward aggressively — not cautiously — and hits a slice approach shot down-the-line.','After the slice, Player 1 continues moving forward and takes up a solid net position near the T.','Player 2 attempts a passing shot from behind the baseline — Player 1 volleys the finish.','Play out each exchange as a mini-point. Repeat 15 times per set.']::text[], ARRAY['Move forward into the ball — don''t stop your feet and hit a static slice.','Keep the racket high on the backswing, then slice down and through the ball on contact.','Aim DTL with the slice approach — the net is lower on the DTL side and it cuts off the CC pass.','After the slice, keep moving toward the net — don''t admire or watch the shot land.','Split step as Player 2 is about to hit the passing shot — react from a balanced position.']::text[], ARRAY['Stopping feet before hitting the slice — should be moving through the shot the whole time.','Floating the slice too high — gives the opponent a comfortable mid-height passing shot.','Staying at the baseline after the approach — defeats the entire tactical purpose of this pattern.']::text[], ARRAY['Player 2 can pass to either side — Player 1 must read and volley both directions.','Give Player 1 a choice: slice DTL or topspin CC — Player 2 must guess the direction before it lands.','Scoring match: Player 1 gets +1 for volley winners, Player 2 gets +1 for passing shot winners.']::text[], ARRAY['slice','approach','net play','down-the-line','intermediate']::text[], 'json', '{"p1":{"x":120,"y":730},"p2":{"x":280,"y":60},"moves":[{"x1":120,"y1":860,"x2":120,"y2":730},{"x1":120,"y1":720,"x2":155,"y2":530}],"shots":[{"x1":280,"y1":70,"x2":110,"y2":690},{"x1":115,"y1":720,"x2":90,"y2":110}],"areas":[{"x":90,"y":110,"r":25}]}'::jsonb),
  ('GW-010', 'High Topspin Backhand Loop', 'Groundwork', 'Backhand', 'groundstrokes', 'advanced', 10, 2, 'pairs', 'Train the high topspin backhand — the shot used against heavy topspin balls that bounce above chest or shoulder height. This is one of the most technically demanding shots in tennis because it requires generating topspin while swinging at an extreme upward angle. It is the essential response to Nadal-style heavy topspin to the backhand and is a weakness of nearly all intermediate players.', 'Train the high topspin backhand — the shot used against heavy topspin balls that bounce above chest or shoulder height. This is one of the most technically demanding shots in tennis because it requires generating topspin while swinging at an extreme upward angle. It is the essential response to Nadal-style heavy topspin to the backhand and is a weakness of nearly all intermediate players.', 'Player 2 feeds or hits heavy topspin balls designed to bounce between chest and shoulder height to Player 1''s backhand. Player 1 must generate a looping topspin backhand back cross-court, keeping it deep.', ARRAY['Player 2 hits a heavy topspin ball aimed at Player 1''s backhand, bouncing between chest and shoulder height.','Player 1 takes the ball slightly late if possible — letting it drop makes it much easier to generate topspin.','Player 1 drives the racket aggressively from low to high, generating topspin on a high contact point.','Target: deep cross-court, landing within 3 feet of the baseline.','Repeat 15 times per set, 3 sets with 60-second rest between each.']::text[], ARRAY['Let the ball drop slightly after the peak if you can — chest height is far easier than shoulder height.','Loop the racket down and back below the ball completely before driving upward.','Drive through the ball and finish high — racket ends well above your head.','For two-handers: the dominant hand brushes up aggressively while the non-dominant hand guides the direction.','Create space with a small side step — hitting while cramped inside the ball kills all power.']::text[], ARRAY['Blocking the high ball instead of swinging through it — produces a weak, floated reply with no depth.','Not creating enough space laterally — body too close, cramped swing.','Swinging flat on a high ball — goes long without topspin to bring it back down.']::text[], ARRAY['Player 2 mixes shoulder-high and waist-high balls unpredictably — Player 1 adjusts swing path accordingly.','High backhand loop then run-around: after the high backhand, Player 1 runs around the next ball for a forehand.','Target bonus: +2 points for any high backhand landing within 2 feet of the baseline.']::text[], ARRAY['backhand','high ball','topspin','advanced','heavy spin']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":280,"y":60},"shots":[{"x1":280,"y1":70,"x2":100,"y2":800},{"x1":110,"y1":840,"x2":295,"y2":95}],"areas":[{"x":295,"y":110,"r":30}]}'::jsonb),
  ('GW-011', 'Forehand Inside-In Winner', 'Groundwork', 'Forehand', 'groundstrokes', 'advanced', 10, 2, 'pairs', 'Train the inside-in forehand — the companion and complement to the inside-out forehand. After luring the opponent to cover the inside-out cross-court, the inside-in forehand fires down-the-line to the deuce corner. This two-shot combination (inside-out followed by inside-in) is one of the most potent tactical patterns in modern professional tennis and virtually impossible to defend against when executed with good disguise.', 'Train the inside-in forehand — the companion and complement to the inside-out forehand. After luring the opponent to cover the inside-out cross-court, the inside-in forehand fires down-the-line to the deuce corner. This two-shot combination (inside-out followed by inside-in) is one of the most potent tactical patterns in modern professional tennis and virtually impossible to defend against when executed with good disguise.', 'Player 1 runs around their backhand and hits an inside-in forehand to the deuce side down-the-line. Player 2 feeds from the ad-side of the opposite baseline, simulating a ball that would normally draw a backhand.', ARRAY['Player 2 feeds a ball to Player 1''s backhand area, slightly left of center.','Player 1 runs around the ball and sets up as if hitting an inside-out forehand cross-court.','Instead of going cross-court, Player 1 fires down-the-line to the deuce corner — the inside-in.','Player 1 must disguise the shot — the setup and backswing should look identical to inside-out until contact.','Repeat 12 times per set. Focus entirely on the surprise element and on precise placement.']::text[], ARRAY['Same setup as inside-out — the disguise is the entire weapon. Identical preparation is non-negotiable.','To go inside-in: rotate hips through the ball more aggressively, driving the strings across the ball.','Your hips must fully clear to allow a down-the-line path from an open stance.','High-risk shot — always aim inside the line by at least 1 foot for a real margin.','Use inside-in sparingly in matches — overuse completely removes the surprise element that makes it work.']::text[], ARRAY['Going for inside-in from a defensive or stretched position — wrong tactical choice, extremely risky.','Not disguising the shot — the opponent reads the DTL direction early and covers it easily.','Hitting too close to the line with no margin — leads to unforced errors that hurt momentum.']::text[], ARRAY['Pattern drill: 2 inside-out forehands then 1 inside-in — simulates the exact combo used in match play.','Player 2 starts cheating toward the CC after the 2nd ball — Player 1 must exploit with inside-in on the 3rd.','Play the point after the inside-in — tests what happens when the inside-in doesn''t end the point outright.']::text[], ARRAY['forehand','inside-in','advanced','pattern','winner','disguise']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":850,"x2":120,"y2":850}],"shots":[{"x1":200,"y1":70,"x2":155,"y2":840},{"x1":120,"y1":840,"x2":300,"y2":90}],"areas":[{"x":300,"y":100,"r":28}],"cones":[{"x":300,"y":100}]}'::jsonb),
  ('GW-012', 'Defensive Slice Under Full Pace', 'Groundwork', 'Slice', 'groundstrokes', 'intermediate', 12, 2, 'pairs', 'Train the ability to slice defensively under full-pace pressure — the match situation where the slice backhand is not a choice but a necessity. When pushed wide or severely stretched, the slice is often the only shot available. This drill teaches players to stay composed, absorb pace with a controlled slice, and reset the point rather than attempting too much from a compromised position.', 'Train the ability to slice defensively under full-pace pressure — the match situation where the slice backhand is not a choice but a necessity. When pushed wide or severely stretched, the slice is often the only shot available. This drill teaches players to stay composed, absorb pace with a controlled slice, and reset the point rather than attempting too much from a compromised position.', 'Player 2 hits hard, wide balls to Player 1''s backhand corner — as wide and fast as possible. Player 1 is forced to sprint and stretch for every ball and return with a slice backhand deep cross-court. The goal is not winning the point: it is getting the ball back deep and recovering position.', ARRAY['Player 2 hits a hard, wide ball to Player 1''s backhand, ideally past the singles sideline.','Player 1 sprints wide, stretches as needed, and slices the ball back deep cross-court.','Player 1 recovers immediately to center after the slice — no lingering at the sideline.','Player 2 keeps feeding hard wide balls — Player 1 must slice every single one.','Score: +1 for each slice landing in the target zone, -1 for each error. Play 15 balls per round.']::text[], ARRAY['Don''t try to do too much from a stretched position — depth and neutral direction are the goals.','Reach across the body if needed — the slice allows more stretch than topspin ever can.','Open the racket face more when fully stretched — it lifts the ball safely over the net.','Priority order: get the ball back first, depth second, direction third.','Recovery after the defensive slice is equally as important as the slice itself — don''t admire the shot.']::text[], ARRAY['Going for a winner from a stretched defensive position — the worst time to be aggressive.','Slice landing short — gives the opponent an easy attack ball on a plate.','Slow recovery after the stretch — concedes the open court completely.']::text[], ARRAY['Recovery sprint: after the defensive slice, Player 2 immediately hits to the opposite side — Player 1 must cover.','One-set challenge: Player 1 must slice 10 consecutive balls into the target zone without a single error.','Combine with counterattack: after 3 defensive slices, Player 1 is allowed to go offensive on the 4th.']::text[], ARRAY['slice','defensive','wide ball','recovery','intermediate']::text[], 'json', '{"p1":{"x":55,"y":820},"p2":{"x":280,"y":60},"moves":[{"x1":150,"y1":850,"x2":55,"y2":820}],"shots":[{"x1":280,"y1":70,"x2":50,"y2":780},{"x1":50,"y1":810,"x2":300,"y2":120}],"areas":[{"x":300,"y":130,"r":35}]}'::jsonb),
  ('GW-013', 'Two-Ball Forehand Sequence: Build then Attack', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 12, 2, 'pairs', 'Develop the ability to hit two consecutive forehands in a deliberate tactical sequence — first cross-court to build the point, then down-the-line to attack and end it. This simulates one of the most common point-winning patterns in competitive tennis at every level: use the CC forehand to draw the opponent wide, then redirect DTL to the open court.', 'Develop the ability to hit two consecutive forehands in a deliberate tactical sequence — first cross-court to build the point, then down-the-line to attack and end it. This simulates one of the most common point-winning patterns in competitive tennis at every level: use the CC forehand to draw the opponent wide, then redirect DTL to the open court.', 'Player 2 feeds two balls per sequence — both to Player 1''s forehand side. Player 1 hits the first cross-court to establish the rally, and the second down-the-line to attack.', ARRAY['Player 2 feeds the first ball to Player 1''s forehand — Player 1 hits cross-court safely and deeply.','Player 2 immediately feeds the second ball to Player 1''s forehand — Player 1 drives down-the-line.','Player 1 recovers to center after both shots.','Rest 10 seconds, then repeat. Do 15 sequences per set.','Progression: after 2 sets, play out the point freely after the DTL shot.']::text[], ARRAY['Shot 1 cross-court: aim deep and central — no risk here, just control and depth.','Shot 2 DTL: wait for a slightly shorter ball to attack — don''t go DTL from behind the baseline.','Recovery between shots is crucial — split step before Shot 2 or you''ll be caught flat-footed.','Disguise the DTL on Shot 2: preparation should look identical to Shot 1 until the last possible moment.','Breathe and exhale between shots — tension kills smooth strokes on both balls.']::text[], ARRAY['Going DTL on Shot 1 — misses the entire tactical purpose of building cross-court first.','Poor recovery between shots — leads to rushed, late preparation on Shot 2.','Telegraphing the DTL on Shot 2 with a different backswing or body position.']::text[], ARRAY['Reverse the pattern: DTL first then CC — tests directional flexibility in both orders.','Three-ball sequence: CC, CC, DTL — more realistic rally build-up before the attack.','Player 2 decides the second target randomly — Player 1 must adjust to the call.']::text[], ARRAY['forehand','sequence','pattern','cross-court','down-the-line','intermediate']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":70,"x2":285,"y2":840},{"x1":285,"y1":840,"x2":95,"y2":110}],"areas":[{"x":95,"y":110,"r":25},{"x":110,"y":840,"r":25}]}'::jsonb),
  ('GW-014', 'Backhand Spin Variation Rally', 'Groundwork', 'Backhand', 'groundstrokes', 'advanced', 15, 2, 'pairs', 'Develop the ability to vary spin on the backhand deliberately during a live rally — alternating between topspin, flat, and slice within the same exchange. Spin variation is a high-level tactical weapon: it disrupts rhythm, creates unexpected bounces, forces opponents into uncomfortable positions, and hides your intentions until the last moment.', 'Develop the ability to vary spin on the backhand deliberately during a live rally — alternating between topspin, flat, and slice within the same exchange. Spin variation is a high-level tactical weapon: it disrupts rhythm, creates unexpected bounces, forces opponents into uncomfortable positions, and hides your intentions until the last moment.', 'Both players rally cross-court backhands. Player 1 must verbally call the spin type before each shot — ''topspin'', ''flat'', or ''slice''. This vocal commitment forces deliberate spin selection rather than defaulting habitually to one spin type.', ARRAY['Begin a cross-court backhand rally at medium pace.','Before each shot, Player 1 calls the spin they will use loudly — before starting the swing.','Player 1 alternates in a pattern: topspin, flat, slice, topspin, flat, slice — or any deliberate mix.','Player 2 simply rallies normally and observes how each different spin affects the bounce and rhythm.','After 10 minutes, Player 2 takes over the spin-calling role — Player 1 must execute on command.']::text[], ARRAY['Topspin: low-to-high swing path, slightly closed racket face at contact, finish high above the shoulder.','Flat: more horizontal swing path, slightly open racket face, drive aggressively through the ball.','Slice: high-to-low path, open face, stay sideways through contact — don''t open the body.','Notice how each spin produces a distinctly different follow-through — they must feel different.','Advanced goal: use the same backswing for all three spins — the spin separation happens at contact only.']::text[], ARRAY['Defaulting to only one spin regardless of the call — completely defeats the purpose of the drill.','Using visibly different backswings for different spins — immediately telegraphs to smart opponents.','Not calling the spin before the shot — removes all intentionality and turns it into a random rally.']::text[], ARRAY['Player 2 calls the spin for Player 1 — removes Player 1''s choice and demands real-time adaptability.','Disguise challenge: Player 1 calls one spin out loud but actually hits a different one — tests if Player 2 reads it.','Live match format: the point is played out freely, but Player 1 must use all three spins at least once per rally.']::text[], ARRAY['backhand','spin variation','topspin','slice','flat','advanced','tactical']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":280,"y":60},"shots":[{"x1":120,"y1":840,"x2":295,"y2":100},{"x1":290,"y1":70,"x2":110,"y2":830},{"x1":115,"y1":830,"x2":290,"y2":100}],"areas":[{"x":295,"y":115,"r":30},{"x":110,"y":820,"r":30}]}'::jsonb),
  ('GW-015', 'Forehand Speed Escalation Rally', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Train the forehand to maintain technique and consistency as pace escalates progressively. Players start at slow pace and increase every 5 shots until they reach maximum speed. This drill reveals exactly at what pace technique breaks down for each player — and then trains them to push that personal threshold higher through repetition.', 'Train the forehand to maintain technique and consistency as pace escalates progressively. Players start at slow pace and increase every 5 shots until they reach maximum speed. This drill reveals exactly at what pace technique breaks down for each player — and then trains them to push that personal threshold higher through repetition.', 'Both players rally cross-court forehands starting at 30% pace. Every 5 shots, both players increase one level: slow to medium to fast to maximum. No exceptions — both players increase together at the same time.', ARRAY['Start the rally at 30% pace — very controlled, smooth strokes with full preparation.','After 5 shots, both players increase to 50% pace together.','After 5 more shots, increase to 75% pace.','After 5 more shots, go to absolute maximum pace.','When an error occurs, note the pace level — that is the current ceiling. Reset and rebuild from slow.']::text[], ARRAY['As pace increases, shorten the backswing slightly — there is simply less available time.','Keep your footwork sharp at high speeds — footwork is almost always the first thing to degrade.','At maximum pace, swing shorter but faster — not shorter and weaker.','Breathe consistently through the drill — tension builds at high speeds and kills consistency.','Watch the ball all the way to the strings at high speed — at pace, eyes tend to anticipate not track.']::text[], ARRAY['Using the same full backswing at maximum pace — inevitably leads to late contact.','Arms tensing up as pace increases — produces inconsistent mis-hits despite trying harder.','Stopping footwork when the rally gets fast — poor positioning causes every problem downstream.']::text[], ARRAY['Only one player escalates, the other stays steady — tests how one player handles asymmetric pressure.','Time-based version: increase pace every 10 seconds instead of every 5 shots.','Sudden drop: at maximum pace, one player suddenly drops to slow — the other must adjust immediately.']::text[], ARRAY['forehand','pace control','escalation','intermediate','pressure']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":120,"y":60},"shots":[{"x1":280,"y1":840,"x2":110,"y2":90},{"x1":120,"y1":70,"x2":275,"y2":835}],"areas":[{"x":110,"y":100,"r":35},{"x":280,"y":820,"r":35}]}'::jsonb),
  ('GW-016', 'Moonball Forehand: High and Heavy', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Develop the moonball forehand — a high, looping topspin ball that lands deep in the court. The moonball is a critical tactical reset tool: it slows down aggressive opponents, pushes players behind the baseline, buys time to recover from a defensive position, and disrupts the rhythm of power hitters who want the ball low and fast. It is an underused yet highly effective weapon.', 'Develop the moonball forehand — a high, looping topspin ball that lands deep in the court. The moonball is a critical tactical reset tool: it slows down aggressive opponents, pushes players behind the baseline, buys time to recover from a defensive position, and disrupts the rhythm of power hitters who want the ball low and fast. It is an underused yet highly effective weapon.', 'Player 2 feeds from the baseline. Player 1 must hit every forehand as a moonball — the ball must clear the net by at least 5 feet and land deep in the court near the baseline. A racket held above Player 2''s head serves as a visual guide for the minimum arc height.', ARRAY['Player 2 feeds medium-paced balls to Player 1''s forehand.','Player 1 hits every forehand as a moonball — high arc, heavy topspin, deep landing.','The ball should clear the net by at least 5 feet (use a racket held above Player 2''s head as a clearance guide).','Target: land within 4 feet of the baseline.','Play 20 moonballs per set. Target: 16 out of 20 in the target zone.']::text[], ARRAY['The moonball is NOT a soft shot — it is a heavy, spun ball hit with a full, committed swing.','Exaggerate the upward swing path dramatically — low-to-very-high finish above the head.','Brush aggressively up the back of the ball — the topspin is what brings it back down despite the high arc.','Aim your finish toward the sky, not toward the opponent — trust the topspin to bring it in.','The high bounce is confirmation of good topspin — it should jump up past the opponent''s shoulder.']::text[], ARRAY['Hitting softly instead of brushing heavily — lands in the middle of the court with no depth.','Insufficient arc — ball sails long without enough topspin to bring it back down.','Using a moonball at the wrong tactical moment — inappropriate when close to the net or on a short ball.']::text[], ARRAY['Moonball rally: both players hit moonballs only — tests patience and deep court management.','Moonball then attack: Player 1 hits 3 moonballs to push Player 2 back, then attacks the short ball.','Match restriction: Player 1 must use at least one moonball in every rally during a practice set.']::text[], ARRAY['forehand','moonball','topspin','tactical','intermediate','high ball']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":840,"x2":200,"y2":110}],"areas":[{"x":200,"y":110,"r":40}],"cones":[{"x":200,"y":250}]}'::jsonb),
  ('GW-017', 'Backhand Slice Keep-Away', 'Groundwork', 'Slice', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Train the slice backhand as an offensive tactical keep-away tool — deliberately directing the ball to the area furthest from where the opponent is standing. Unlike the defensive slice, where the goal is simply surviving, the keep-away slice is a proactive, placement-first shot designed to exploit court position and create open court.', 'Train the slice backhand as an offensive tactical keep-away tool — deliberately directing the ball to the area furthest from where the opponent is standing. Unlike the defensive slice, where the goal is simply surviving, the keep-away slice is a proactive, placement-first shot designed to exploit court position and create open court.', 'Player 2 stands at the net or T-position and moves visibly left or right. Player 1 must read Player 2''s movement and slice to the opposite side of the court — wherever Player 2 is NOT.', ARRAY['Player 2 stands at the net and feeds a short ball to Player 1''s backhand.','Player 2 then moves visibly to one side of the net after feeding.','Player 1 must slice past Player 2 to the opposite, open side.','If Player 2 moves left, Player 1 slices right. If Player 2 moves right, Player 1 slices left.','Play 15 sequences per set. Score +1 for each successful keep-away slice that passes Player 2.']::text[], ARRAY['Read Player 2''s movement as early as possible — don''t wait until the last second to decide direction.','The slice is ideal for keep-away because it stays low and passes through the court quickly.','Guide the slice with your non-dominant hand — it steers the direction precisely.','No big, elaborate swings — a compact, directed slice is far more accurate than a full swing here.','Aim 1-2 feet inside the line at all times — always give yourself a real margin for error.']::text[], ARRAY['Hitting toward where Player 2 is standing — not reading the court positioning before swinging.','Floating the slice — gives Player 2 time to recover and cover the open side.','Overhitting aggressively — a controlled, precise slice beats a slapped winner attempt every time.']::text[], ARRAY['Player 2 moves after Player 1 has already started the swing — tests late-reading ability.','Player 2 does not move — Player 1 must independently choose the best angle.','Full point play: Player 2 at net versus Player 1 at baseline — Player 1 must use slice at least once.']::text[], ARRAY['slice','backhand','tactical','keep-away','intermediate','placement']::text[], 'json', '{"p1":{"x":120,"y":750},"p2":{"x":250,"y":480},"shots":[{"x1":250,"y1":490,"x2":110,"y2":710},{"x1":110,"y1":740,"x2":330,"y2":150}],"areas":[{"x":330,"y":150,"r":25}]}'::jsonb),
  ('GW-018', 'Backhand Redirect: Cross-Court to DTL', 'Groundwork', 'Backhand', 'groundstrokes', 'advanced', 12, 2, 'pairs', 'Master the backhand redirect — changing the direction of an incoming cross-court ball to go down-the-line. This is a signature move of elite players: drawing the opponent cross-court then redirecting DTL. The technical challenge is maintaining complete disguise and adjusting the contact point subtly while handling high-pace balls — the two skills that make this shot impossible to defend.', 'Master the backhand redirect — changing the direction of an incoming cross-court ball to go down-the-line. This is a signature move of elite players: drawing the opponent cross-court then redirecting DTL. The technical challenge is maintaining complete disguise and adjusting the contact point subtly while handling high-pace balls — the two skills that make this shot impossible to defend.', 'Player 2 hits cross-court to Player 1''s backhand side at medium-high pace, creating a realistic cross-court ball. Player 1 must redirect every single ball down-the-line while keeping the setup completely identical.', ARRAY['Player 2 initiates a cross-court backhand ball at medium-high pace.','Player 1 must redirect every shot down-the-line — changing the direction of a ball coming cross-court.','After 10 minutes of DTL-only, Player 1 is given freedom to choose CC or DTL per shot.','Player 2 must guess the direction before Player 1 hits each shot.','Score: +1 for Player 1 if Player 2 guesses wrong, +1 for Player 2 if correct.']::text[], ARRAY['Contact point is slightly later than cross-court — let the ball travel a fraction further toward you.','Keep shoulders closed longer to create the DTL redirect from the backhand side.','Do NOT overhit the redirect — the direction change itself is the weapon, not added pace.','Your preparation and backswing must look identical for both CC and DTL.','For two-handers: the non-dominant hand can push the follow-through direction subtly DTL.']::text[], ARRAY['Too-early contact — ball goes cross-court instead of DTL regardless of intent.','Opening the body to redirect — immediately telegraphs the DTL direction to the opponent.','Redirecting from a defensive or stretched position — should only redirect on neutral or offensive balls.']::text[], ARRAY['Continuous sequence: Player 2 goes CC, Player 1 redirects DTL, back and forth non-stop.','Player 2 hits short every 4th ball — Player 1 must approach the net after redirecting.','Full point: Player 2 must start CC but Player 1 can redirect at any point in the rally.']::text[], ARRAY['backhand','redirect','DTL','disguise','advanced','pattern']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":280,"y":60},"shots":[{"x1":280,"y1":70,"x2":115,"y2":820},{"x1":115,"y1":840,"x2":90,"y2":100}],"areas":[{"x":90,"y":100,"r":28}],"cones":[{"x":90,"y":100}]}'::jsonb),
  ('GW-019', 'Forehand Angled Short Cross', 'Groundwork', 'Forehand', 'groundstrokes', 'advanced', 10, 2, 'pairs', 'Develop the ability to create extreme angles with the forehand by stepping inside the court and hitting a sharp cross-court that lands inside the service box. The angled short cross is a point-ending shot when hit precisely — it pulls opponents completely off the court, opens the entire opposite side, and is one of the most aesthetically satisfying shots in tennis when executed cleanly.', 'Develop the ability to create extreme angles with the forehand by stepping inside the court and hitting a sharp cross-court that lands inside the service box. The angled short cross is a point-ending shot when hit precisely — it pulls opponents completely off the court, opens the entire opposite side, and is one of the most aesthetically satisfying shots in tennis when executed cleanly.', 'Player 2 feeds a short ball (inside the service line) to Player 1''s forehand side. Player 1 must step well inside the court and hit a sharply angled cross-court forehand that lands inside the service box area.', ARRAY['Player 2 feeds a short ball inside Player 1''s service line to the forehand.','Player 1 moves forward aggressively and steps inside the court before hitting.','Player 1 hits a sharp angled cross-court forehand — the ball must land inside the service box.','Player 1 recovers to center baseline immediately after the shot.','Play 15 times per set. Count how many balls land inside the target zone in the service box.']::text[], ARRAY['Step well inside the court before hitting — the inside-the-court position is what enables extreme angles.','Open the racket face and brush across the outside of the ball — create sidespin, not just topspin.','The swing path goes more sideways than forward — like a windshield wiper, not a straight drive.','Aim for the far doubles alley line at the net level — the angle from there creates the sharp landing.','This is a short-ball-only shot — never attempt it from behind or even near the baseline.']::text[], ARRAY['Attempting this shot from behind the baseline — geometrically impossible angle, always goes wide.','Swinging too straight — produces a regular cross-court with no extra angle.','Not stepping inside the court first — reduces the available angle dramatically.']::text[], ARRAY['Inside-out then short angle: Player 1 hits inside-out to open the court, then moves in for the angle.','Follow the angle to the net: after the angled shot, Player 1 rushes the net and finishes with a volley.','Two-shot combo: regular deep CC then sharp angle — forces opponent to cover completely different depths.']::text[], ARRAY['forehand','angle','short cross','advanced','winner','approach']::text[], 'json', '{"p1":{"x":280,"y":645},"p2":{"x":200,"y":60},"moves":[{"x1":280,"y1":860,"x2":280,"y2":645}],"shots":[{"x1":200,"y1":70,"x2":280,"y2":615},{"x1":280,"y1":635,"x2":65,"y2":375}],"areas":[{"x":65,"y":375,"r":22}],"cones":[{"x":65,"y":375}]}'::jsonb),
  ('GW-020', 'Forehand–Backhand Transition Under Pressure', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 12, 2, 'pairs', 'Train the rapid transition between forehand and backhand under genuine time pressure — simulating being pushed side to side rapidly in a match. This drill forces players to switch grips mid-sprint, adjust footwork patterns between completely different stances, and maintain stroke quality and depth under physical and mental fatigue — the conditions that cause most unforced errors in matches.', 'Train the rapid transition between forehand and backhand under genuine time pressure — simulating being pushed side to side rapidly in a match. This drill forces players to switch grips mid-sprint, adjust footwork patterns between completely different stances, and maintain stroke quality and depth under physical and mental fatigue — the conditions that cause most unforced errors in matches.', 'Player 2 feeds balls rapidly — alternating wide to the forehand then wide to the backhand with minimal rest between feeds. Player 1 must reach each ball at full sprint and return it into the court.', ARRAY['Player 1 starts at center baseline in the ready position.','Player 2 feeds wide to the forehand — Player 1 runs at full sprint, hits, and sprints back to center.','Player 2 immediately feeds wide to the backhand — Player 1 sprints, hits, and returns to center.','Continue for 8 total balls (4 forehand, 4 backhand), then rest 45 seconds. Repeat 4 rounds.','Intentional focus: don''t just return the ball — hit with direction and depth under fatigue.']::text[], ARRAY['Grip change must happen during the sprint — not after arriving at the ball.','Even when stretched, take a full swing — don''t poke or jab defensively.','Your first step after hitting should always be directly back toward center.','Use your non-dominant arm as a counterbalance when sprinting wide — helps balance.','Your split step will be the first thing to suffer under fatigue — consciously fight to maintain it.']::text[], ARRAY['Forgetting to change grip during the sprint — causes hitting backhand with forehand grip.','Jogging to wide balls instead of sprinting — drills must replicate genuine match pace.','Failing to recover fully to center — stopping halfway allows easy exploitation.']::text[], ARRAY['Progressive rounds: 6 balls, then 8, then 10, then 12 — increasing workload each round.','Player 2 varies depth as well — some balls wide AND short, forcing diagonal sprints.','Bonus attack: Player 2 hits 4 wide balls then drops a short ball — Player 1 attacks the short ball.']::text[], ARRAY['forehand','backhand','transition','pressure','fitness','intermediate']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"moves":[{"x1":200,"y1":850,"x2":335,"y2":850},{"x1":335,"y1":850,"x2":200,"y2":850},{"x1":200,"y1":850,"x2":65,"y2":850}],"shots":[{"x1":200,"y1":70,"x2":335,"y2":840},{"x1":200,"y1":60,"x2":65,"y2":840}],"areas":[{"x":200,"y":120,"r":45}]}'::jsonb),
  ('GW-021', 'Backhand Block Return', 'Groundwork', 'Backhand', 'groundstrokes', 'beginner', 8, 2, 'pairs', 'Develop the backhand block — a compact, controlled stroke used to absorb pace and redirect hard incoming shots. The block is essential against flat, fast balls when there is not enough time for a full swing. It is the technical foundation of the return of serve and every defensive backhand situation in match play.', 'Develop the backhand block — a compact, controlled stroke used to absorb pace and redirect hard incoming shots. The block is essential against flat, fast balls when there is not enough time for a full swing. It is the technical foundation of the return of serve and every defensive backhand situation in match play.', 'Player 2 hits hard, flat balls directly at Player 1''s backhand from the service line — simulating a hard, fast serve or aggressive groundstroke. Player 1 must block every ball back using a compact swing with no big backswing.', ARRAY['Player 2 stands at the service line and hits hard, flat balls to Player 1''s backhand.','Player 1 uses a compact backhand block — no loop backswing, just a controlled redirect.','The goal is to keep the ball in play and redirect it back — not to hit a winner.','After 10 blocks, Player 2 adds more pace — Player 1 continues to block.','Switch roles after 8 minutes so both players train the block.']::text[], ARRAY['Start with your racket already up in the ready position — no loop backswing on a block.','Meet the ball in front of your body — not beside or behind your hip.','Keep a firm wrist throughout — a floppy wrist produces erratic, uncontrolled direction.','Open the racket face very slightly to lift the ball safely over the net.','Think of yourself as a redirecting wall: the ball comes at you, you redirect its energy.']::text[], ARRAY['Taking a full loop backswing — there is no time for it on fast balls.','Floppy or collapsing wrist — causes major mis-hits and unpredictable direction.','Not meeting the ball early enough — late contact causes the ball to jam the body.']::text[], ARRAY['Block and sprint: Player 2 hits to the backhand, Player 1 blocks and immediately sprints to the net.','Blind block: Player 1 closes their eyes for 1 second after the feed, then opens and blocks.','Block plus counter: after 3 blocks, Player 1 is allowed to counter-attack aggressively on the 4th.']::text[], ARRAY['backhand','block','return','compact swing','beginner','defensive']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":200,"y":480},"shots":[{"x1":200,"y1":490,"x2":110,"y2":820},{"x1":110,"y1":840,"x2":290,"y2":100}],"areas":[{"x":290,"y":120,"r":40}]}'::jsonb),
  ('GW-022', 'Forehand Contact Point Awareness', 'Groundwork', 'Forehand', 'groundstrokes', 'intermediate', 10, 2, 'pairs', 'Isolate and improve the contact point for the forehand drive. Power and consistency on the forehand depend overwhelmingly on where the ball is contacted relative to the body — too close jams the swing, too far extends the arm awkwardly. This drill builds awareness and muscle memory for the ideal contact zone through varied feeds that force footwork adjustment.', 'Isolate and improve the contact point for the forehand drive. Power and consistency on the forehand depend overwhelmingly on where the ball is contacted relative to the body — too close jams the swing, too far extends the arm awkwardly. This drill builds awareness and muscle memory for the ideal contact zone through varied feeds that force footwork adjustment.', 'Player 2 feeds balls from a basket to Player 1''s forehand at deliberately varying speeds and spins — slow, medium, and fast. Player 1 must adjust footwork before every ball to ensure contact always happens at the same ideal point.', ARRAY['Player 2 feeds varying balls: slow, medium, and fast — all to the forehand side.','Player 1 must adjust footwork to ensure every ball is contacted at the same point — roughly arm''s length in front of the lead hip.','Player 1 calls ''contact!'' out loud at the exact moment of hitting — forces conscious awareness.','After 20 balls, Player 2 adds topspin feeds to change the bounce height.','Repeat 3 rounds of 20 balls each.']::text[], ARRAY['Extend your dominant arm forward — that distance is roughly where contact should happen.','A crisp, clean sound at contact confirms the right spot. A dull thud often means too close.','Always adjust your feet to the ball — never adjust your arm to compensate for bad footwork.','On slow balls: step forward into the ball. On fast balls: allow the ball to come to you.','Keep your eyes focused on the ball all the way to the strings — never look away early.']::text[], ARRAY['Letting the ball get too close to the body — jams the entire swing and kills power.','Reaching too far out for the ball — extends the arm awkwardly and removes all power.','Using the arm to compensate for bad footwork — leads to inconsistent contact.']::text[], ARRAY['Eyes closed: Player 1 closes eyes, Player 2 calls ''hit'' — Player 1 opens and makes contact.','Towel drill: place a small towel at the ideal contact point as a physical reference.','Add lateral movement before each feed — simulates realistic match conditions.']::text[], ARRAY['forehand','contact point','technique','power','intermediate']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":200,"y":480},"shots":[{"x1":200,"y1":490,"x2":285,"y2":820},{"x1":285,"y1":840,"x2":110,"y2":100}],"areas":[{"x":110,"y":100,"r":30}]}'::jsonb),
  ('GW-023', 'Slice Backhand: Low vs. High Ball Adaptation', 'Groundwork', 'Slice', 'groundstrokes', 'advanced', 12, 2, 'pairs', 'Train the slice technique adaptation for both very low balls and very high balls. The slice backhand changes significantly depending on ball height: a low slice requires bending the knees and getting below the ball, while a high slice requires an entirely different racket path from above the ball. Elite players manage both effortlessly — most club players handle only one comfortably.', 'Train the slice technique adaptation for both very low balls and very high balls. The slice backhand changes significantly depending on ball height: a low slice requires bending the knees and getting below the ball, while a high slice requires an entirely different racket path from above the ball. Elite players manage both effortlessly — most club players handle only one comfortably.', 'Player 2 feeds balls alternating between very low (short, low-bouncing) and very high (heavy topspin). Player 1 must slice every single ball but use appropriate technique for each specific height.', ARRAY['Player 2 feeds a low ball — Player 1 slices with bent knees, staying below the ball.','Player 2 feeds a high ball — Player 1 slices from above with a high-to-low path.','Alternate continuously for 10 pairs. Player 1 must read the height early and adjust completely.','After 10 pairs, Player 2 feeds randomly without signaling — Player 1 must identify and react.','Play 20 random balls, rest 60 seconds, repeat 3 sets.']::text[], ARRAY['Low ball: get your racket lower than the ball — bend the knees, never bend the back.','Low ball: swing slightly upward through contact and open the face more to lift over the net.','High ball: take the racket above the ball first, then slice down and through it.','High ball: take it early at the peak of the bounce — don''t let it drop further.','Read the bounce height at the moment of the second bounce — gives ample time to adjust.']::text[], ARRAY['Using the same swing path for both heights — at least one will always be technically wrong.','Bending the back instead of the knees on low balls — causes spine strain and poor contact.','Letting the high ball drop too low before slicing — gives the opponent time to get into position.']::text[], ARRAY['Forehand slice on high balls, backhand slice on low — or vice versa for extra challenge.','Add approach to the net after every slice — Player 1 slices then follows into the net.','Live points: Player 2 can mix heights and depths freely — Player 1 must slice everything.']::text[], ARRAY['slice','backhand','low ball','high ball','advanced','technique']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":200,"y":480},"shots":[{"x1":200,"y1":490,"x2":110,"y2":800},{"x1":110,"y1":840,"x2":290,"y2":110}],"areas":[{"x":290,"y":100,"r":25}]}'::jsonb),
  ('GW-024', 'Forehand Swing Volley', 'Groundwork', 'Forehand', 'groundstrokes', 'advanced', 10, 2, 'pairs', 'Develop the forehand swing volley — a full forehand groundstroke taken out of the air before the ball bounces. The swing volley is used to take moonballs and high floaters early at the net, creating extreme angles and ending points decisively. It requires perfect timing, deliberate footwork, and the mental commitment to take a full swing at the net rather than punching.', 'Develop the forehand swing volley — a full forehand groundstroke taken out of the air before the ball bounces. The swing volley is used to take moonballs and high floaters early at the net, creating extreme angles and ending points decisively. It requires perfect timing, deliberate footwork, and the mental commitment to take a full swing at the net rather than punching.', 'Player 2 feeds a relatively high, slow, looping ball (simulating a moonball or a lob that didn''t go over). Player 1 is positioned inside the service line and must take the ball out of the air with a complete forehand swing.', ARRAY['Player 1 positions inside the service line at the net.','Player 2 feeds a high, looping ball that would bounce around the service line.','Player 1 lets the ball drop to the correct strike zone and takes a full forehand swing volley.','Player 1 aims to put the ball away — the swing volley should be an offensive shot.','Repeat 12 times. Focus on timing and directing the ball away from Player 2.']::text[], ARRAY['Take the ball at the peak or just after the peak of its arc — don''t let it drop too far.','Take a full forehand swing — not a punch. The swing is what creates pace and topspin.','Step into the ball just like a baseline groundstroke — use your body momentum.','Aim away from where Player 2 is standing — create angles to open court.','Keep your eye on the ball — swing volleys are often mis-hit when looking at the court.']::text[], ARRAY['Taking a short punch volley instead of a full swing — wastes the opportunity entirely.','Letting the ball drop too far before swinging — contact point is too low for power.','Standing flat-footed with no footwork — no momentum means no power.']::text[], ARRAY['Feeds from different positions — Player 1 must swing volley from anywhere inside the service line.','Swing volley then volley: Player 2 answers and Player 1 must finish with a regular punch volley.','High stakes: Player 2 can pass if Player 1 mis-hits the swing volley — adds real match stakes.']::text[], ARRAY['forehand','swing volley','net','advanced','timing','winner']::text[], 'json', '{"p1":{"x":280,"y":590},"p2":{"x":120,"y":60},"moves":[{"x1":280,"y1":860,"x2":280,"y2":590}],"shots":[{"x1":120,"y1":70,"x2":280,"y2":560},{"x1":280,"y1":580,"x2":340,"y2":100}],"areas":[{"x":340,"y":110,"r":25}]}'::jsonb),
  ('GW-025', 'Forehand Short Angle Winner', 'Groundwork', 'Forehand', 'groundstrokes', 'advanced', 10, 2, 'pairs', 'Master the short-angle forehand winner — a sharply angled shot landing close to the doubles sideline inside the service box. This shot is the finishing blow after an inside-out pattern or any situation where the opponent has been pulled wide. It requires stepping inside the court and creating deliberate sidespin — making it one of the most lethal finishing shots in the game.', 'Master the short-angle forehand winner — a sharply angled shot landing close to the doubles sideline inside the service box. This shot is the finishing blow after an inside-out pattern or any situation where the opponent has been pulled wide. It requires stepping inside the court and creating deliberate sidespin — making it one of the most lethal finishing shots in the game.', 'Player 2 feeds a short ball (inside the service line) to Player 1''s forehand. Player 1 must sprint forward, step inside the court, and hit a sharp angled forehand that lands inside the service box.', ARRAY['Player 2 feeds a short ball just inside the service line to Player 1''s forehand side.','Player 1 sprints forward and steps well inside the court before contact.','Player 1 hits a sharp forehand angle — the ball must land between the singles sideline and center service line, inside the service box.','Player 1 recovers immediately to center baseline.','Repeat 15 times per set. Count how many land inside the target zone.']::text[], ARRAY['Step forward and inside the ball completely — your body''s momentum must be moving through the shot.','Brush across the outside of the ball to create sidespin — this is what creates the sharp angle.','Follow through more sideways than upward — the racket path creates the angle, not the wrist.','Aim for the far doubles alley line at the net level — from inside the court, this creates a lethal angle.','This is a short-ball-only shot — never attempt from near or behind the baseline.']::text[], ARRAY['Attempting from behind the baseline — geometrically impossible angle, always goes wide.','Brushing too straight — produces a regular cross-court without the additional angle.','Not stepping inside the court — dramatically reduces the available angle.']::text[], ARRAY['Short angle then approach: after the angle, Player 1 rushes the net to finish.','Setup first: Player 1 must hit 2 deep baseline balls before the short angle on the 3rd.','Opposite side: Player 2 is pulled wide — Player 1 creates the angle to the open court.']::text[], ARRAY['forehand','angle','winner','short ball','advanced']::text[], 'json', '{"p1":{"x":200,"y":640},"p2":{"x":280,"y":60},"moves":[{"x1":200,"y1":860,"x2":200,"y2":640}],"shots":[{"x1":280,"y1":70,"x2":195,"y2":610},{"x1":195,"y1":630,"x2":65,"y2":350}],"areas":[{"x":65,"y":350,"r":22}],"cones":[{"x":65,"y":350}]}'::jsonb),
  ('GW-026', 'Backhand Consistency: 50-Ball Challenge', 'Groundwork', 'Backhand', 'groundstrokes', 'beginner', 15, 2, 'pairs', 'Build deep concentration and consistency on the cross-court backhand through high-volume repetition and mental pressure. The 50-ball challenge forces players to maintain focus, technique, and intention long past the point where it feels comfortable — the exact conditions of long baseline rallies in match play. Any error resets the count, which creates real mental accountability.', 'Build deep concentration and consistency on the cross-court backhand through high-volume repetition and mental pressure. The 50-ball challenge forces players to maintain focus, technique, and intention long past the point where it feels comfortable — the exact conditions of long baseline rallies in match play. Any error resets the count, which creates real mental accountability.', 'Both players rally cross-court backhands. The challenge: complete 50 consecutive shots without any error. Any error — into the net, wide, or down-the-line — immediately resets the count back to zero.', ARRAY['Begin a cross-court backhand rally. One player counts shots aloud, clearly.','Every shot must land in the correct cross-court half. DTL shots don''t count and reset to 0.','Any net or out error resets the count immediately to 0.','Target: reach 50 consecutive shots in a single session.','If 50 becomes easy, progress to 75 or 100.']::text[], ARRAY['Focus only on the current shot — never think about the count when you''re at 35 or 40.','Breathe between every shot — tension builds with the count and causes the errors you fear.','Reduce pace deliberately as the count gets high — consistency over ego.','Keep your footwork active — complacency and flat feet creep in on high counts.','If you miss at 48, restart with exactly the same mental freshness as shot 1.']::text[], ARRAY['Increasing pace as the count gets high — ego overriding the actual goal.','Mental tightness at 30+ causing tense shots that go long or wide.','Inconsistent depth — short balls break the rhythm and pressure the partner.']::text[], ARRAY['Depth rule: only shots landing past the service line count toward the total.','Direction alternation: alternate CC and DTL — must land correctly in both directions.','Time version: how many consecutive shots can both players land in exactly 3 minutes?']::text[], ARRAY['backhand','consistency','challenge','cross-court','mental','beginner']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":280,"y":60},"shots":[{"x1":120,"y1":840,"x2":290,"y2":90},{"x1":290,"y1":70,"x2":115,"y2":835}],"areas":[{"x":290,"y":110,"r":35},{"x":115,"y":820,"r":35}]}'::jsonb),
  ('GW-027', 'Forehand Counterpunch at High Pace', 'Groundwork', 'Forehand', 'groundstrokes', 'advanced', 12, 2, 'pairs', 'Develop the forehand counterpunch — the ability to absorb extreme pace from an opponent and redirect it cross-court with equal or greater depth and spin. Counterpunching is a specific, trainable skill distinct from blocking (passive) and attacking (offensive) — it takes an aggressive incoming ball and drives it back just as hard, changing the direction and creating pressure rather than simply surviving.', 'Develop the forehand counterpunch — the ability to absorb extreme pace from an opponent and redirect it cross-court with equal or greater depth and spin. Counterpunching is a specific, trainable skill distinct from blocking (passive) and attacking (offensive) — it takes an aggressive incoming ball and drives it back just as hard, changing the direction and creating pressure rather than simply surviving.', 'Player 2 hits hard, flat balls to Player 1''s forehand at 80-90% of their full pace. Player 1 must counterpunch every ball cross-court, matching or exceeding the pace of the incoming ball.', ARRAY['Player 2 hits a hard forehand to Player 1''s forehand side at near-maximum pace.','Player 1 must drive back a counterpunch cross-court — matching or exceeding the pace.','Both players hit near their maximum pace throughout the drill.','Play 10-ball sequences at full intensity. Rest 90 seconds between sequences.','Play 5 complete sequences. Track errors and winners from both players.']::text[], ARRAY['Don''t back away from the pace — lean in and take the ball early, not late.','Shorten the backswing at high pace — use the incoming ball''s energy intelligently.','Stay balanced at all times — the temptation to lean too far forward is strong under pace.','Drive your legs through contact — the lower body absorbs and redirects the force.','Reset your feet after every single exchange — never be flat-footed when the next ball arrives.']::text[], ARRAY['Backing off the ball — turns into a defensive block instead of a genuine counterpunch.','Arm-only swing without leg drive — lacks the power to match the incoming pace.','Leaning back at contact — sends the ball long consistently.']::text[], ARRAY['Counterpunch DTL: Player 1 must redirect down-the-line instead of cross-court — harder.','Add a winner: after 6 consecutive counterpunches, Player 1 can try to end the point.','Pressure set: Player 2 tries to win every point at full effort — maximum match intensity.']::text[], ARRAY['forehand','counterpunch','pace','advanced','baseline','power']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":120,"y":60},"shots":[{"x1":120,"y1":70,"x2":280,"y2":830},{"x1":280,"y1":845,"x2":100,"y2":90}],"areas":[{"x":100,"y":100,"r":30},{"x":280,"y":820,"r":30}]}'::jsonb),
  ('GW-028', 'Two-Ball Backhand: Build then Attack DTL', 'Groundwork', 'Backhand', 'groundstrokes', 'intermediate', 12, 2, 'pairs', 'Train the fundamental two-shot backhand sequence in competitive tennis: build the rally cross-court first, then attack down-the-line to finish the point. This is the backbone of backhand-dominant baseline play — use the CC backhand to move the opponent and create a slightly shorter ball, then drive DTL to the open court for a winner.', 'Train the fundamental two-shot backhand sequence in competitive tennis: build the rally cross-court first, then attack down-the-line to finish the point. This is the backbone of backhand-dominant baseline play — use the CC backhand to move the opponent and create a slightly shorter ball, then drive DTL to the open court for a winner.', 'Player 2 feeds two consecutive balls to Player 1''s backhand. Player 1 hits the first cross-court to neutralize, and the second down-the-line to attack.', ARRAY['Player 2 feeds the first ball — Player 1 hits cross-court backhand safely and deeply.','Player 2 feeds the second ball — Player 1 drives down-the-line aggressively.','Player 1 recovers to center between both shots.','Run 15 two-ball sequences per set, 3 sets total.','Progression: play out the point after the DTL shot.']::text[], ARRAY['Shot 1 cross-court: safe, deep, and central — push Player 2 back. No risk on this shot.','Shot 2 DTL: step around if possible — being slightly forward makes DTL far safer.','Disguise: the setup and backswing for Shot 2 must look identical to Shot 1 until contact.','After the DTL, recover immediately — your own DTL opens your cross-court side completely.','Only attack DTL on a shorter ball — don''t go DTL from behind the baseline.']::text[], ARRAY['Both shots going cross-court — not actually executing the DTL on Shot 2.','Going DTL on a ball that''s too deep or too wide — too much risk from a bad position.','No recovery between shots — caught flat-footed on Shot 2.']::text[], ARRAY['Three-shot sequence: CC, CC, DTL — more realistic rally build-up before the attack.','Reverse: DTL first then CC — tests directional flexibility in the opposite order.','Player 2 plays the point out after the DTL — real consequence for good and bad execution.']::text[], ARRAY['backhand','sequence','build','attack','DTL','intermediate']::text[], 'json', '{"p1":{"x":120,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":200,"y1":70,"x2":110,"y2":840},{"x1":110,"y1":840,"x2":295,"y2":110}],"areas":[{"x":295,"y":115,"r":25},{"x":285,"y":95,"r":25}]}'::jsonb),
  ('GW-029', 'Slice Serve + Slice Backhand Combo Pattern', 'Groundwork', 'Slice', 'groundstrokes', 'advanced', 12, 2, 'pairs', 'Combine the slice serve with a slice backhand follow-up shot — a tactically sophisticated two-shot pattern that keeps the ball consistently low. The slice serve pulls the opponent wide off the court. The slice backhand second shot continues the low-ball theme, forcing the opponent to hit upward twice in a row. This pattern is particularly effective on fast courts and is a hallmark of elite serve-and-volley and aggressive baseline players.', 'Combine the slice serve with a slice backhand follow-up shot — a tactically sophisticated two-shot pattern that keeps the ball consistently low. The slice serve pulls the opponent wide off the court. The slice backhand second shot continues the low-ball theme, forcing the opponent to hit upward twice in a row. This pattern is particularly effective on fast courts and is a hallmark of elite serve-and-volley and aggressive baseline players.', 'Player 1 serves wide (slice serve) to the ad court, pulling the opponent wide. Player 2 returns, and Player 1 must follow up with a slice backhand — not a topspin groundstroke — to continue the low-ball pattern.', ARRAY['Player 1 serves a wide slice serve to the ad court.','Player 2 returns from a wide position — Player 1 must hit the next ball as a slice backhand.','Player 1 then plays out the point normally after the slice.','Focus on quality of both the serve and the slice follow-up.','Repeat 12 times, then switch servers.']::text[], ARRAY['Slice serve: brush across and down the ball at contact — a genuine slice motion, not a flat serve.','The slice serve should pull the opponent well outside the singles sideline.','On the follow-up slice: stay low and compact — the slice is the tempo-control shot.','The pattern works because both shots stay low — forces the opponent to hit upward both times.','After the slice follow-up, look for the inevitably short ball to attack.']::text[], ARRAY['Slice serve not curving enough — ends up flat and down the middle.','Following the slice serve with a topspin — defeats the low-ball rhythm of the entire pattern.','Slice follow-up floating too high — gives away the low-ball advantage.']::text[], ARRAY['Body serve plus slice follow-up: jam the opponent''s body then slice to the open court.','Slice serve plus slice drop shot: extreme variation once the low-ball pattern is established.','Doubles version: serve wide plus slice, with partner poaching at the net.']::text[], ARRAY['slice','serve','combination','advanced','pattern','ad court']::text[], 'json', '{"p1":{"x":160,"y":860},"p2":{"x":280,"y":60},"moves":[{"x1":160,"y1":850,"x2":200,"y2":820}],"shots":[{"x1":160,"y1":850,"x2":330,"y2":370},{"x1":280,"y1":70,"x2":200,"y2":760},{"x1":195,"y1":810,"x2":95,"y2":120}],"areas":[{"x":95,"y":120,"r":28}]}'::jsonb),
  ('GW-030', 'Forehand Rip: Maximum Power Training', 'Groundwork', 'Forehand', 'groundstrokes', 'advanced', 10, 2, 'pairs', 'Train hitting the forehand at absolute maximum power — 100% effort — without sacrificing technique. Most players unconsciously hold back in practice out of fear of errors. This drill gives explicit permission to swing as hard as possible and teaches players to find their personal line between power and control. Knowing where that line is — and being able to push it — is what separates competitive players from those who always play safe.', 'Train hitting the forehand at absolute maximum power — 100% effort — without sacrificing technique. Most players unconsciously hold back in practice out of fear of errors. This drill gives explicit permission to swing as hard as possible and teaches players to find their personal line between power and control. Knowing where that line is — and being able to push it — is what separates competitive players from those who always play safe.', 'Player 2 feeds from the opposite service box using a basket. Player 1 hits every forehand at 100% power — absolutely no holding back. Errors are information, not failure.', ARRAY['Player 2 feeds balls to Player 1''s forehand from the opposite service box.','Player 1 rips every forehand at full power — full swing, full rotation, full commitment. No mental brake.','If balls go long: add more topspin by brushing up more aggressively, but maintain pace.','If balls go wide: adjust direction slightly but keep full pace.','Play 25 balls, rest 90 seconds, repeat 3 sets. Track how many land in the court.']::text[], ARRAY['Give yourself explicit permission to miss — this is training for aggression, not perfection.','Drive off the back foot completely — rotate everything: hips, torso, shoulder, arm.','Snap the wrist through contact — the wrist snap adds significant racket head speed.','Keep your eyes on the ball, not on the court — trust the swing, not the aim.','Most players discover they can hit significantly harder than they thought — let that be a revelation.']::text[], ARRAY['Holding back after a few early misses — completely defeats the entire purpose of this drill.','Tensing the arm while trying harder — actually reduces racket head speed.','Closing the stance too much — limits hip rotation and prevents full power.']::text[], ARRAY['Measure with a speed gun or SwingVision app — track forehand speed improvement over weeks.','Power rally: both players rip at 100% — who sustains the longest cross-court rally?','Power with placement: rip at 100%, but must land in one specific target zone.']::text[], ARRAY['forehand','power','aggression','maximum','advanced']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":200,"y":480},"shots":[{"x1":200,"y1":490,"x2":280,"y2":820},{"x1":280,"y1":840,"x2":100,"y2":100}],"areas":[{"x":100,"y":110,"r":30}]}'::jsonb),
  ('MP-001', '21-Point Baseline Tiebreak', 'Matchplay', 'Competitive Play', 'matchplay', 'beginner', 15, 2, 'pairs', 'Introduce competitive match pressure in a condensed, high-repetition format. The 21-point tiebreak is the most efficient match simulation format available — it produces competitive pressure from the very first point, generates a winner quickly, and can be replicated many times in a single session. Unlike a full set, every point in a 21-point tiebreak carries significant weight, making it an excellent format for training competitive mentality without the time investment of a full match.', 'Introduce competitive match pressure in a condensed, high-repetition format. The 21-point tiebreak is the most efficient match simulation format available — it produces competitive pressure from the very first point, generates a winner quickly, and can be replicated many times in a single session. Unlike a full set, every point in a 21-point tiebreak carries significant weight, making it an excellent format for training competitive mentality without the time investment of a full match.', 'Both players rally from the baseline. Points are played out fully. The first player to reach 21 points wins. Win by 2 required. Serve alternates every 2 points. No let rules — all serves are live.', ARRAY['Flip a coin or spin a racket to determine who serves first.','Serve alternates every 2 points throughout — same as a tiebreak.','Play each point fully from the serve — all strokes, volleys, and overheads are live.','Count points aloud after every point — both players must agree on the score.','First to 21 wins, win by 2. Play best of 3 sets of 21-point tiebreaks.']::text[], ARRAY['Every point matters — there are no warm-up points in a tiebreak format.','Track which patterns work: what serves win points? What rally patterns produce errors from the opponent?','Mental reset after each point — whether you won or lost the previous point is irrelevant.','Communication: say the score clearly before every serve — both players must agree.','The 21-point format reveals your competitive instincts quickly — trust them.']::text[], ARRAY['Playing casually instead of competitively — the tiebreak only works with genuine competition.','Score disputes — always agree on the score before serving.','Not tracking patterns — the tiebreak is a data source, not just a competition.']::text[], ARRAY['10-point tiebreak: faster format — first to 10, win by 2.','Handicap tiebreak: weaker player starts at +5 — levels the competition.','Constraint tiebreak: both players must stay behind the service line — tests baseline tactics only.']::text[], ARRAY['matchplay','tiebreak','competitive','beginner','pressure','baseline']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":200,"y1":60,"x2":280,"y2":820},{"x1":280,"y1":830,"x2":100,"y2":100}],"areas":[{"x":280,"y":820,"r":30},{"x":100,"y":100,"r":30}]}'::jsonb),
  ('MP-002', 'First Ball Attack: Win on the Plus-One', 'Matchplay', 'Tactical Patterns', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Develop the tactical habit of winning the point on the very first attack ball — the plus-one after the serve or the return. Modern tennis is dominated by first-ball attack: the server attacks the return, or the returner attacks the second serve. This drill trains the specific mindset and pattern of planning the first attack before the serve and executing it with decisive aggression.', 'Develop the tactical habit of winning the point on the very first attack ball — the plus-one after the serve or the return. Modern tennis is dominated by first-ball attack: the server attacks the return, or the returner attacks the second serve. This drill trains the specific mindset and pattern of planning the first attack before the serve and executing it with decisive aggression.', 'Both players play full points. Player 1 serves. Before each point, Player 1 declares a pattern out loud: for example, ''wide serve, forehand inside-out on the plus-one''. Player 1 must execute the declared pattern. Player 2 plays freely.', ARRAY['Player 1 declares the serve target and plus-one target before each point.','Player 1 serves and must execute the plus-one exactly as declared.','Player 2 returns aggressively and plays out the point.','If Player 1 wins the point on the plus-one: +2 points. If Player 1 wins beyond the plus-one: +1 point. If Player 2 wins: 0.','Play 15 points, then switch servers. First to 15 bonus points wins.']::text[], ARRAY['The declaration forces tactical thinking before the serve — not reactive thinking after.','Choose realistic patterns: wide serve + CC forehand is reliable. Wide serve + DTL is risky.','Move to the plus-one position during the serve — your feet should be moving before the return lands.','Commit to the declared shot — hesitation on the plus-one produces errors.','Over time, build a personal pattern library: 5 deuce court patterns and 5 ad court patterns.']::text[], ARRAY['Declaring patterns and then ignoring the declaration — defeats the entire tactical training.','Overly risky declarations — declaring serves and shots that are technically too difficult.','Plus-one not aggressive enough — must be a genuine attack ball, not a setup ball.']::text[], ARRAY['Return plus-one: Player 2 now declares the return plus-one pattern — tests return game planning.','Three-shot declaration: declare serve, plus-one, and plus-two — extends the tactical planning.','No declaration: play freely but count bonus points for winning on the plus-one — tracks natural tendencies.']::text[], ARRAY['matchplay','serve+1','tactical','intermediate','first ball','pattern']::text[], 'json', '{"p1":{"x":280,"y":840},"p2":{"x":120,"y":60},"moves":[{"x1":240,"y1":855,"x2":280,"y2":840}],"shots":[{"x1":240,"y1":855,"x2":310,"y2":385},{"x1":120,"y1":70,"x2":255,"y2":815},{"x1":278,"y1":838,"x2":95,"y2":100}],"areas":[{"x":95,"y":100,"r":28}]}'::jsonb),
  ('MP-003', 'Deuce and Ad Court Pressure Points', 'Matchplay', 'Pressure Scenarios', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Train the two highest-pressure points in any game: deuce and ad-out. These are the points that determine whether a game is won or lost, and most players play them differently (worse) than non-pressure points. This drill creates concentrated repetitions of exactly these two scenarios, building the habit of playing your best tennis precisely when it matters most.', 'Train the two highest-pressure points in any game: deuce and ad-out. These are the points that determine whether a game is won or lost, and most players play them differently (worse) than non-pressure points. This drill creates concentrated repetitions of exactly these two scenarios, building the habit of playing your best tennis precisely when it matters most.', 'Every single point in this drill starts at either deuce or ad-out — never at any other score. Players alternate between the two scenarios: point 1 at deuce, point 2 at ad-out for Player 1, point 3 at ad-out for Player 2, and so on.', ARRAY['Announce ''deuce'' before the first point — play it fully from the serve.','Announce ''ad-out'' (against Player 1) before the second point — play it fully.','Announce ''ad-in'' (for Player 1) before the third point — play it fully.','Continue rotating these three pressure scenarios for 20 points.','Track: what percentage of deuce points does each player win? What percentage of ad-out points?']::text[], ARRAY['The score before these points is irrelevant — this point is all that matters.','Use the pre-serve breathing protocol — exhale before the toss to release tension.','At deuce: play your best pattern, not your safest pattern. Safest is rarely best.','At ad-out: this is not the time for risky shots — play solid, deep, and let the opponent make an error.','Track the data: players who win 60%+ of deuce points are performing well under pressure.']::text[], ARRAY['Playing more conservatively at deuce than in practice — the mental response to the score is the enemy.','Serving to ''safe'' locations at ad-out — often the most predictable and returnable serves.','Mental chatter during the point — must be in the present moment.']::text[], ARRAY['Deuce only: practice only deuce points — concentrated pressure.','Multiple deuce games: play full games where every game starts at 40-40.','Track the emotional response: journal what you were thinking at each deuce — reveals mental patterns.']::text[], ARRAY['matchplay','deuce','pressure','intermediate','mental','score scenarios']::text[], 'json', '{"p1":{"x":200,"y":850},"p2":{"x":200,"y":60},"shots":[{"x1":240,"y1":855,"x2":200,"y2":375},{"x1":200,"y1":60,"x2":110,"y2":820},{"x1":110,"y1":830,"x2":295,"y2":100}],"areas":[{"x":110,"y":820,"r":28},{"x":295,"y":100,"r":28}]}'::jsonb),
  ('MP-004', 'Short Court Games: Service Box Only', 'Matchplay', 'Tactical Development', 'matchplay', 'beginner', 12, 2, 'pairs', 'Develop touch, feel, net awareness, and short-ball tactics through service box-only matches. When the entire point is confined to the service boxes, players are forced to develop all the shots that most baseline-only players lack: drop shots, angles, half-volleys, drop volleys, and the touch needed for short-ball exchanges. These skills translate directly to all-court play.', 'Develop touch, feel, net awareness, and short-ball tactics through service box-only matches. When the entire point is confined to the service boxes, players are forced to develop all the shots that most baseline-only players lack: drop shots, angles, half-volleys, drop volleys, and the touch needed for short-ball exchanges. These skills translate directly to all-court play.', 'Both players stand inside their respective service boxes. Points are played entirely within the service boxes — any ball landing outside the service box is out. Normal scoring applies.', ARRAY['Both players position inside their service boxes.','Feed the ball underhand to start each point.','All shots must land inside the opponent''s service box — baseline shots are out.','Play to 11 points, win by 2. Switch sides after each game.','Play best of 5 games of 11 points.']::text[], ARRAY['Soft hands are essential — full-swing groundstrokes always go long in this format.','Use all the short-court weapons: drop shots, angles, half-volleys, and touch volleys.','The service box format forces you to vary spin and pace — one-dimensional players lose quickly.','Approach the net whenever possible — the short court rewards net play heavily.','Watch where your opponent is positioned — angles become available when they are pulled wide.']::text[], ARRAY['Hitting too hard — all balls go long in the service box format.','Not varying spin — topspin balls that bounce high go long easily.','Staying at the baseline — must approach the net to create angles.']::text[], ARRAY['One player at net, one at baseline — pure net vs. passing shot competition.','Service box plus: include the service box and the first 3 feet of the backcourt.','Drop shot only: all shots must bounce twice within the service box — extreme touch training.']::text[], ARRAY['matchplay','short court','touch','beginner','angles','net play']::text[], 'json', '{"p1":{"x":200,"y":600},"p2":{"x":200,"y":390},"shots":[{"x1":200,"y1":400,"x2":150,"y2":580},{"x1":150,"y1":570,"x2":260,"y2":420},{"x1":260,"y1":410,"x2":100,"y2":570}],"areas":[{"x":200,"y":600,"r":50},{"x":200,"y":390,"r":50}]}'::jsonb),
  ('MP-005', 'Cross-Court Rally then Open Court Attack', 'Matchplay', 'Tactical Patterns', 'matchplay', 'intermediate', 15, 2, 'pairs', 'Train the foundational competitive rally pattern: build cross-court until a shorter ball appears, then attack the open court. This pattern appears in virtually every baseline exchange at the competitive level — it is not a coincidence that elite players rally cross-court and attack DTL. This drill trains the pattern deliberately, making it habitual and automatic.', 'Train the foundational competitive rally pattern: build cross-court until a shorter ball appears, then attack the open court. This pattern appears in virtually every baseline exchange at the competitive level — it is not a coincidence that elite players rally cross-court and attack DTL. This drill trains the pattern deliberately, making it habitual and automatic.', 'Both players must rally cross-court for the first 4 shots of every point. After 4 cross-court shots, either player may attack in any direction. Both players must count the first 4 shots aloud.', ARRAY['Feed or serve to start the point.','Both players must rally cross-court for the first 4 shots — DTL shots before shot 4 lose the point immediately.','After shot 4, either player may attack in any direction to try to win the point.','Continue playing until the point ends.','Play 20 points. Track: what direction does the first attack go? What percentage of attack shots win?']::text[], ARRAY['The first 4 cross-court shots build the pattern — aim deep and to the corners.','Watch for the shorter ball within the first 4 shots — that is the attack trigger.','After shot 4: go DTL or angle if you have a short ball. Stay CC if the ball is deep.','Most points in competitive tennis are won after 4-9 shots — this drill replicates that.','Track which player attacks first after shot 4 — the first attacker usually wins the point.']::text[], ARRAY['Attacking before shot 4 — breaks the drill and doesn''t train the pattern.','Continuing to rally CC after shot 4 even when a short ball appears — missing the attack trigger.','Attacking DTL from a neutral or defensive position — poor tactical judgment.']::text[], ARRAY['5-shot rule: must rally cross-court for 5 shots before attacking.','Bonus points: +2 for winning the point on the shot immediately after the 4th.','Single player constraint: only Player 1 must follow the cross-court rule — Player 2 plays freely.']::text[], ARRAY['matchplay','cross-court','attack','intermediate','pattern','tactical']::text[], 'json', '{"p1":{"x":280,"y":850},"p2":{"x":120,"y":60},"shots":[{"x1":280,"y1":840,"x2":110,"y2":90},{"x1":120,"y1":70,"x2":275,"y2":835},{"x1":275,"y1":840,"x2":95,"y2":90},{"x1":110,"y1":70,"x2":295,"y2":100}],"areas":[{"x":95,"y":90,"r":28},{"x":295,"y":100,"r":28}]}'::jsonb)
